<?php require_once __DIR__.'/../../middleware/bootstrap.php';require_once __DIR__.'/../../config/database.php';require_admin();$stats=[];foreach(['users'=>'users','packages'=>'tour packages','bookings'=>'bookings'] as $t=>$k){$stats[$k]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();}$stats['pending_bookings']=(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE booking_status='pending'")->fetchColumn();$recent=$pdo->query('SELECT b.id,b.travel_date,b.booking_status,u.name customer_name,p.package_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN packages p ON p.id=b.package_id ORDER BY b.created_at DESC LIMIT 8')->fetchAll();json_out(['stats'=>$stats,'recent_bookings'=>$recent]);
